require_once __DIR__.'/../includes/bootstrap.php';require_role('Accounts Officer','Super Admin','College Admin');page_top('Payment Ledger');?><div class='card p-3 table-responsive'><table class='table'><tr><th>Reference</th><th>Student</th><th>Amount</th><th>Provider</th><th>Status</th><th>Paid At</th></tr><?php $q=db()->query('SELECT p.reference,p.amount,u.name,p.provider,p.status,p.paid_at FROM payments p JOIN students s ON s.id=p.student_id JOIN users u ON u.id=s.user_id ORDER BY p.id DESC');foreach($q as $r):?><tr><?php foreach($r as $v):?><td><?=e($v)?></td><?php endforeach;?></tr><?php endforeach;?></table></div><?php page_bottom();